/* Responsive phone navigation and appointment agenda. */
function phoneMenu(open){document.body.classList.toggle('phone-menu-open',open);document.getElementById('phoneMenuButton')?.setAttribute('aria-expanded',String(open))}
function phoneNavigate(next){phoneMenu(false);navigate(next);window.scrollTo?.({top:0,behavior:'smooth'})}
function renderPhoneShell(){
 let bar=document.getElementById('phoneBar');if(!bar){bar=document.createElement('div');bar.id='phoneBar';document.body.appendChild(bar)}
 bar.innerHTML=`<a class="phone-brand" href="#" onclick="phoneNavigate('overview');return false">SEVLINK<span>PROPERTY MAINTENANCE</span></a><button id="phoneMenuButton" aria-label="Open navigation menu" aria-expanded="${document.body.classList.contains('phone-menu-open')}" onclick="phoneMenu(!document.body.classList.contains('phone-menu-open'))">☰ Menu</button>`;
 let bottom=document.getElementById('phoneNav');if(!bottom){bottom=document.createElement('nav');bottom.id='phoneNav';bottom.setAttribute('aria-label','Phone navigation');document.body.appendChild(bottom)}
 const links=[['overview','◫','Home'],['requests','☷','Jobs'],['calendar','▦','Calendar'],...(role==='tenant'?[['report','＋','Report']]:role==='sevlink'?[['privateplanner','◷','Planner']]:[['properties','⌂','Properties']])];
 bottom.innerHTML=links.map(([v,icon,label])=>`<button class="${view===v?'active':''}" ${view===v?'aria-current="page"':''} onclick="phoneNavigate('${v}')"><span aria-hidden="true">${icon}</span>${label}</button>`).join('');
 let shade=document.getElementById('phoneShade');if(!shade){shade=document.createElement('button');shade.id='phoneShade';shade.setAttribute('aria-label','Close navigation menu');shade.onclick=()=>phoneMenu(false);document.body.appendChild(shade)}
 document.querySelectorAll('table').forEach(table=>{const labels=Array.from(table.querySelectorAll('thead th')).map(th=>th.textContent.trim());if(!labels.length)return;table.classList.add('phone-cards');table.querySelectorAll('tbody tr').forEach(row=>Array.from(row.children).forEach((cell,i)=>{cell.dataset.label=labels[i]||''}))});
}
const renderBeforePhone=render;render=function(){renderBeforePhone();renderPhoneShell()};
const navigateBeforePhone=navigate;navigate=function(next){phoneMenu(false);return navigateBeforePhone(next)};
function phoneVisitCard(j){const s=j.schedule;return `<button class="phone-visit" onclick="openCalendarAppointment('${esc(j.id)}','${esc(s.when)}')"><span class="phone-visit-date">${esc(attendanceTime(s.when))}</span><strong>${esc(property(j.property)?.name||property(j.property)?.address||'Property')}</strong><b>${esc(j.title||j.category||'Maintenance visit')}</b><span>${s.status==='Attended'?'✓ Appointment completed':s.onSiteAt?'● Sevlink on site':'Sevlink attending'} · ${esc(j.ref||'')}</span><span class="phone-open">View appointment →</span></button>`}
const calendarBeforePhone=renderCalendar;renderCalendar=function(){calendarBeforePhone();const prefix=calendarMonth.getFullYear()+'-'+String(calendarMonth.getMonth()+1).padStart(2,'0'),jobs=calendarJobs().filter(j=>j.schedule.when.startsWith(prefix)).sort((a,b)=>a.schedule.when.localeCompare(b.schedule.when));const grid=app.querySelector('.calendar-grid');if(grid)grid.insertAdjacentHTML('afterend',`<div class="phone-agenda"><p class="muted">Appointments this month · SAST</p>${jobs.map(phoneVisitCard).join('')||'<div class="notice">No appointments this month. Use the arrows to choose another month.</div>'}</div>`)};
const plannerBeforePhone=renderPrivatePlanner;renderPrivatePlanner=function(){plannerBeforePhone();if(role!=='sevlink'||plannerTab!=='calendar')return;const days=calendarDayKeys(),bookings=filteredPrivateBookings().filter(b=>days.includes(b.when.slice(0,10))),grid=app.querySelector('.private-calendar-scroll');if(grid)grid.insertAdjacentHTML('afterend',`<div class="phone-agenda"><p class="muted">Private assignments · SAST</p>${bookings.map(b=>{const j=bookingJob(b);return `<button class="phone-visit" onclick="privateBookingDetail('${esc(b.id)}')"><span class="phone-visit-date">${esc(attendanceTime(b.when))}</span><strong>${esc(property(j?.property)?.name||'Property')}</strong><b>${esc(j?.title||'Maintenance visit')}</b><span>${esc(bookingSubbie(b)?.name||'Unassigned')} · ${esc(b.status)}</span><span class="phone-open">Open private job card →</span></button>`}).join('')||'<div class="notice">No assignments in this period.</div>'}</div>`)};
document.addEventListener('keydown',event=>{if(event.key==='Escape')phoneMenu(false)});

